      }
      is NativeInteropAllClassesWrapper -> {
        stream.write(135)
        writeValue(stream, value.toList())
      }
      is NativeInteropSealedClassWithFields -> {
        stream.write(136)
        writeValue(stream, value.toList())
      }
      is NativeInteropEmptySealedClass -> {
        stream.write(137)
        writeValue(stream, value.toList())
      }
      is NativeInteropSealedClassWrapper -> {
        stream.write(138)
        writeValue(stream, value.toList())
      }
      is NativeInteropReservedNames -> {
